    }

    fn below(&mut self, n: u32) -> u32 {
        self.next_u32() % n
    }
}

fn drain_all(mem: &mut [u8], layout: &MemoryLayout, out: &mut Vec<Opcode>) {
    let mut h = Host::new(mem, layout);
    for frame in h.frames() {
        out.extend(frame.opcodes());
    }
}

